	/* ================= LENTELE ================= */

	public static function lentele() {
		global $wpdb;
		return $wpdb->prefix . self::LENTELE;
	}

	public static function install() {
		global $wpdb;
		if ( get_option( self::DB_VERSIJA_OPT ) === self::VERSIJA ) { return; }
		$T = self::lentele();
		$c = $wpdb->get_charset_collate();
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
		dbDelta( "CREATE TABLE `$T` (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			flow VARCHAR(64) NOT NULL,
			version INT UNSIGNED NOT NULL DEFAULT 1,
			status VARCHAR(16) NOT NULL DEFAULT 'draft',
			subject TEXT NULL,
			preheader TEXT NULL,
			reason TEXT NULL,
			blocks_json LONGTEXT NULL,
			notes TEXT NULL,
			author_id BIGINT UNSIGNED NULL,
			created_at DATETIME NULL,
			published_at DATETIME NULL,
			PRIMARY KEY (id),
			KEY flow_status (flow, status),
			KEY flow_version (flow, version)
		) $c;" );
		update_option( self::DB_VERSIJA_OPT, self::VERSIJA, false );
	}

	/* ================= SKAITYMAS ================= */

	public static function paskelbtas( $flow ) {
		global $wpdb;
		$T = self::lentele();
		if ( $wpdb->get_var( "SHOW TABLES LIKE '$T'" ) !== $T ) { return null; }
		$r = $wpdb->get_row( $wpdb->prepare(
			"SELECT * FROM `$T` WHERE flow=%s AND status='published' ORDER BY version DESC LIMIT 1", $flow
		), ARRAY_A );
		if ( ! $r ) { return null; }
		$r['blocks'] = json_decode( (string) $r['blocks_json'], true );
		if ( ! is_array( $r['blocks'] ) ) { $r['blocks'] = array(); }
		return $r;
	}

